const N = 22;
f[]@bud_x = []; f[]@bud_y = []; f[]@bud_z = []; f[]@bud_c = []; f[]@bud_t = [];
for (let i = 0; i < N; i++) {
  const y = 1 - 1.55 * (i + 0.5) / N, r = sqrt(max(0, 1 - y * y)), a = i * 2.399963 + TAU * rand(seed, 1);
  const c = normalize(add([r * cos(a), y, r * sin(a)], mul(randdir(i * 31 + seed), 0.12)));
  @bud_x.push(c.x); @bud_y.push(c.y); @bud_z.push(c.z);
  @bud_c.push(1 - cos(0.3 * (0.75 + 0.5 * rand(i, seed, 2))));
  @bud_t.push(floor(8 * rand(i, seed, 3)));
}

const bx = detail(0, 'bud_x'), by = detail(0, 'bud_y'), bz = detail(0, 'bud_z'), bc = detail(0, 'bud_c'), bt = detail(0, 'bud_t');
const dx = v@dir.x, dy = v@dir.y, dz = v@dir.z;
let bud = 0;
for (let i = 0; i < bx.length; i++) {
  if (iteration < bt[i]) continue;
  const u = (1 - (dx * bx[i] + dy * by[i] + dz * bz[i])) / bc[i];
  if (u < 1) { const s = max(0, u - 0.0625) / 0.9375, f = 1 - s * s * (3 - 2 * s); if (f > bud) bud = f; }
}
const lobe = 1 + 0.7 * lumpiness * snoise(mul(v@dir, 12), seed + 9);
const g = (1 - lumpiness) * 0.6 + lumpiness * lobe * 2.4 * bud * bud;
const base = smoothstep(-0.95, -0.4, dy);
const d = normalize(add(mul(normalize(@P), 0.5), mul(@N, 0.5)));
@P = add(@P, mul(d, rate * g * base));

const R = 1.6 * edge_length;
let push = [0, 0, 0];
for (const j of nearpoints(0, @P, R, 8)) {
  if (j === @ptnum) continue;
  const q = point(0, 'P', j), nq = point(0, 'N', j);
  const dv = sub(@P, q), dist = length(dv);
  if (dist > 1e-9 && dot(@N, nq) < -0.3 && dot(nq, dv) > 0) push = add(push, mul(dv, 0.5 * (R - dist) / dist));
}
@P = add(@P, push);
